"""Independent re-implementation of the k-colour palette-state accounting.

Deliberately different code path from state_enum.py:
  * labels as bitmasks, not frozensets;
  * allowed values generated by scanning 1..2^k-1 rather than by combinations();
  * bipartiteness decided ALGEBRAICALLY: G is bipartite iff the diagonal of A^m
    vanishes for every odd m <= n (equivalently A is not "odd-walk-closed"),
    checked by repeated multiplication over the integers (exact), not by BFS;
  * odd-cycle witness extracted from an odd closed walk found by matrix search,
    then reduced to a simple odd cycle by a separate routine and verified edge
    by edge;
  * orbit counts by iterating the adjacency matrix, exact integer arithmetic.
"""
import itertools, json, hashlib

def allowed_masks(k, ell):
    Ec = [(i, (i+1) % ell) for i in range(ell)]
    out = []
    lim = 1 << k
    for m in range(1, lim):
        sz = bin(m).count("1")
        if sz > k-3:
            continue
        bad = False
        for (i, j) in Ec:
            em = (1 << i) | (1 << j)
            if m & ~em == 0:
                bad = True; break
        if not bad:
            out.append(m)
    out.sort(key=lambda m: (bin(m).count("1"), m))
    return out

def labels(m):
    return [i for i in range(16) if m >> i & 1]

import numpy as np

def _bm(M):
    return np.array(M, dtype=bool)

def matmul(A, B):
    # boolean matrix product: exists a two-step walk
    return np.dot(A.astype(np.int32), B.astype(np.int32)) > 0

def has_odd_closed_walk(A):
    """returns (m, i) with a closed walk of odd length m <= 2n+1 at i, else None.
    Boolean reachability powers (exact, no truncation)."""
    An = _bm(A); n = An.shape[0]
    P = np.eye(n, dtype=bool)          # A^0
    for m in range(1, 2*n+2):
        P = matmul(P, An) if m > 1 else An.copy()
        if m % 2 == 1:
            for i in range(n):
                if P[i, i]:
                    return (m, i)
    return None

def odd_closed_walk_path(A, m, i):
    """explicit closed walk of length m at vertex i, via DP"""
    n = len(A)
    # dp[r][v] = a walk of length r from i to v, stored as vertex list
    dp = [None]*(m+1)
    dp[0] = {i: [i]}
    for r in range(m):
        nd = {}
        for v, path in dp[r].items():
            for w in range(n):
                if A[v][w] and w not in nd:
                    nd[w] = path + [w]
        dp[r+1] = nd
    return dp[m].get(i)

def reduce_to_simple_odd_cycle(walk):
    """walk is a closed walk v0..vm with v0=vm; repeatedly remove closed sub-walks
    of even length to keep the length odd and the walk simple."""
    w = walk[:]
    changed = True
    while changed:
        changed = False
        n = len(w)-1
        for a in range(n):
            if changed: break
            for b in range(a+2, n+1):
                if w[a] == w[b]:
                    sub = b - a
                    if sub % 2 == 0 and sub < n:
                        w = w[:a+1] + w[b+1:]
                        changed = True
                        break
    return w

def independent_sets_check(A, colours):
    n = len(A)
    for i in range(n):
        for j in range(i+1, n):
            if A[i][j] and colours[i] == colours[j]:
                return False
    return True

def core(vals, colours, c):
    s = None
    for i, v in enumerate(vals):
        if colours[i] == c:
            s = v if s is None else (s & v)
    return s if s is not None else 0

def main():
    report = {}
    for k in (5, 6):
        for ell in range(3, k+1):
            vals = allowed_masks(k, ell)
            n = len(vals)
            A = [[0 if i == j else (1 if (vals[i] & vals[j]) == 0 else 0) for j in range(n)] for i in range(n)]
            for i in range(n): A[i][i] = 0
            occ = [i for i in range(n) if any(A[i])]
            valso = [vals[i] for i in occ]
            no = len(occ)
            Ao = [[A[occ[i]][occ[j]] for j in range(no)] for i in range(no)]
            res = {"k": k, "ell": ell, "n_allowed": n, "n_occurring": no,
                   "occurring": [labels(v) for v in valso]}
            ow = has_odd_closed_walk(Ao)
            if ow is None:
                # construct a 2-colouring by the algebraic certificate: colour by
                # parity of distance from vertex 0 (BFS-free: use A powers)
                dist = [None]*no
                dist[0] = 0
                Pn = np.eye(no, dtype=bool)
                for d in range(1, no+1):
                    Pn = matmul(Pn, _bm(Ao))
                    for v in range(no):
                        if dist[v] is None and Pn[0, v]:
                            dist[v] = d
                colours = [d % 2 for d in dist]
                assert all(c is not None for c in colours)
                assert independent_sets_check(Ao, colours)
                g0, g1 = core(valso, colours, 0), core(valso, colours, 1)
                res.update({"bipartite": True,
                            "odd_cycle_witness": None,
                            "groups": [labels(g0), labels(g1)],
                            "E2": (bin(g0).count("1")+bin(g1).count("1") == k-2 and g0 and g1),
                            "E3": (bin(g0).count("1")+bin(g1).count("1") == k-1 and g0 and g1)})
            else:
                m, i = ow
                walk = odd_closed_walk_path(Ao, m, i)
                cyc = reduce_to_simple_odd_cycle(walk)
                # verify: closed, odd, simple, and every consecutive pair disjoint
                ok = (cyc[0] == cyc[-1] and (len(cyc)-1) % 2 == 1
                      and len(set(cyc[:-1])) == len(cyc)-1
                      and all(Ao[cyc[t]][cyc[t+1]] for t in range(len(cyc)-1)))
                res.update({"bipartite": False,
                            "odd_cycle_verified": ok,
                            "odd_cycle_len": len(cyc)-1,
                            "odd_cycle_witness": [labels(valso[x]) for x in cyc],
                            "E2": False, "E3": False, "groups": None})
            # direct count of admissible orbit data = #closed walks of length 6,
            # by per-start DP (a different computation path from matrix powers)
            tot = 0
            for s0 in range(no):
                cur = {s0: 1}
                for _ in range(5):
                    nxt = {}
                    for v, c in cur.items():
                        for w in range(no):
                            if Ao[v][w]:
                                nxt[w] = nxt.get(w, 0) + c
                    cur = nxt
                tot += sum(c for v, c in cur.items() if Ao[v][s0])
            res["n_orbit_data"] = tot
            # longest engine-independent pairs with |A|+|B| = k-2  (Theorem A targets)
            tgt = []
            for i in range(no):
                for j in range(no):
                    if Ao[i][j] and bin(valso[i]).count("1")+bin(valso[j]).count("1") == k-2:
                        tgt.append([labels(valso[i]), labels(valso[j])])
            res["thmA_targets"] = tgt
            report[f"k{k}_ell{ell}"] = res
    txt = json.dumps(report, sort_keys=True, indent=1)
    open("states_k5_k6_b.json","w").write(txt)
    print(f"{'key':10s} {'#occ':>4s} {'bip':>5s} {'#orbits':>9s} {'E2':>5s} {'E3':>5s}  Theorem-A targets (|A|+|B|=k-2, disjoint)")
    for key in sorted(report):
        e = report[key]
        print(f"{key:10s} {e['n_occurring']:4d} {str(e['bipartite']):>5s} {e['n_orbit_data']:9d} {str(e['E2']):>5s} {str(e['E3']):>5s}  "
              + ("; ".join(f"{a}+{b}" for a,b in e["thmA_targets"]) if e["thmA_targets"] else "-")
              + ("" if e["bipartite"] else f"   [odd cycle verified={e['odd_cycle_verified']}, len={e['odd_cycle_len']}]"))
    print("SHA256:", hashlib.sha256(txt.encode()).hexdigest())

main()
